mod.js:
morse.on(window, "keydown", e => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const t = e.target;
  if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
  if (e.key !== "j" && e.key !== "k") return;
  const secs = morse.$$("#apicontent > section");
  if (!secs.length) return;
  let idx = -1;
  secs.forEach((s, i) => { if (s.getBoundingClientRect().top <= 142) idx = i; });
  let next = e.key === "j" ? idx + 1 : idx - 1;
  next = Math.max(0, Math.min(secs.length - 1, next));
  e.preventDefault();
  secs[next].scrollIntoView({ behavior: "smooth", block: "start" });
});

