mod.js:
morse.watch(".tbl > h3", h => {
  if (h.querySelector(".csv-btn")) return;
  const btn = morse.el("button", {
    class: "csv-btn",
    text: "Download CSV",
    on: {
      click: () => {
        const table = h.parentElement.querySelector(".sc table");
        if (!table) return morse.toast("No table found");
        const rows = [...table.querySelectorAll("tr")].map(tr =>
          [...tr.children].map(c => {
            const t = c.textContent.trim().replace(/"/g, '""');
            return /[",\n]/.test(t) ? `"${t}"` : t;
          }).join(",")
        );
        const blob = new Blob([rows.join("\n")], { type: "text/csv" });
        const a = morse.el("a", { href: URL.createObjectURL(blob), download: "recent-orders.csv" });
        document.body.appendChild(a);
        a.click();
        a.remove();
        morse.toast("CSV downloaded");
      }
    }
  });
  h.appendChild(btn);
});

